import { SuperProperties } from '../src/SuperProperties';
import type { JSONSerializable } from '../src/types';

describe('SuperProperties', () => {
  beforeEach(() => {
    // Clear super properties before each test
    SuperProperties.clearSuperProperties();
  });

  describe('addToSuperProperties', () => {
    it('should add a single property', () => {
      SuperProperties.addToSuperProperties('app_version', '1.0.0');
      const props = SuperProperties.getSuperProperties();
      expect(props.app_version).toBe('1.0.0');
    });

    it('should add multiple properties', () => {
      SuperProperties.addToSuperProperties('app_version', '1.0.0');
      SuperProperties.addToSuperProperties('platform', 'web');
      SuperProperties.addToSuperProperties('language', 'en');

      const props = SuperProperties.getSuperProperties();
      expect(props).toEqual({
        app_version: '1.0.0',
        platform: 'web',
        language: 'en',
      });
    });

    it('should update existing property', () => {
      SuperProperties.addToSuperProperties('app_version', '1.0.0');
      SuperProperties.addToSuperProperties('app_version', '2.0.0');

      const props = SuperProperties.getSuperProperties();
      expect(props.app_version).toBe('2.0.0');
    });

    it('should accept string values', () => {
      SuperProperties.addToSuperProperties('name', 'test');
      expect(SuperProperties.getSuperProperties().name).toBe('test');
    });

    it('should accept number values', () => {
      SuperProperties.addToSuperProperties('count', 42);
      expect(SuperProperties.getSuperProperties().count).toBe(42);
    });

    it('should accept boolean values', () => {
      SuperProperties.addToSuperProperties('active', true);
      expect(SuperProperties.getSuperProperties().active).toBe(true);
    });

    it('should accept null values', () => {
      SuperProperties.addToSuperProperties('value', null);
      expect(SuperProperties.getSuperProperties().value).toBeNull();
    });
  });

  describe('getSuperProperties', () => {
    it('should return empty object when no properties set', () => {
      const props = SuperProperties.getSuperProperties();
      expect(props).toEqual({});
    });

    it('should return a copy of properties', () => {
      SuperProperties.addToSuperProperties('key', 'value');
      const props1 = SuperProperties.getSuperProperties();
      const props2 = SuperProperties.getSuperProperties();

      expect(props1).toEqual(props2);
      expect(props1).not.toBe(props2); // Different references
    });

    it('should not be affected by modifying returned object', () => {
      SuperProperties.addToSuperProperties('key', 'value');
      const props = SuperProperties.getSuperProperties();

      // Modify the returned object
      (props as any).newKey = 'newValue';

      // Original should not be affected
      const newProps = SuperProperties.getSuperProperties();
      expect(newProps).not.toHaveProperty('newKey');
    });

    it('should return all set properties', () => {
      SuperProperties.addToSuperProperties('a', 1);
      SuperProperties.addToSuperProperties('b', 2);
      SuperProperties.addToSuperProperties('c', 3);

      const props = SuperProperties.getSuperProperties();
      expect(Object.keys(props)).toHaveLength(3);
      expect(props).toEqual({ a: 1, b: 2, c: 3 });
    });
  });

  describe('clearSuperProperties', () => {
    it('should clear all properties', () => {
      SuperProperties.addToSuperProperties('a', 1);
      SuperProperties.addToSuperProperties('b', 2);

      SuperProperties.clearSuperProperties();

      const props = SuperProperties.getSuperProperties();
      expect(props).toEqual({});
    });

    it('should allow adding properties after clearing', () => {
      SuperProperties.addToSuperProperties('a', 1);
      SuperProperties.clearSuperProperties();

      SuperProperties.addToSuperProperties('b', 2);

      const props = SuperProperties.getSuperProperties();
      expect(props).toEqual({ b: 2 });
    });

    it('should be idempotent', () => {
      SuperProperties.addToSuperProperties('a', 1);
      SuperProperties.clearSuperProperties();
      SuperProperties.clearSuperProperties();
      SuperProperties.clearSuperProperties();

      const props = SuperProperties.getSuperProperties();
      expect(props).toEqual({});
    });
  });

  describe('integration with SudoQuery', () => {
    it('should merge super properties with event properties', () => {
      SuperProperties.addToSuperProperties('platform', 'web');
      SuperProperties.addToSuperProperties('app_version', '1.0.0');

      const props = SuperProperties.getSuperProperties();
      expect(props.platform).toBe('web');
      expect(props.app_version).toBe('1.0.0');
    });

    it('should allow event properties to override super properties', () => {
      SuperProperties.addToSuperProperties('platform', 'web');

      const superProps = SuperProperties.getSuperProperties();
      const eventProps = { platform: 'mobile' };

      // Simulate merge behavior
      const merged = { ...superProps, ...eventProps };
      expect(merged.platform).toBe('mobile');
    });
  });
});

import { Pusher } from "../src/Pusher";
import { Batcher } from "../src/Batcher";
import { Configuration } from "../src/Configuration";
import type { Event } from "../src/types";

// Mock Flush module
jest.mock("../src/Flush", () => ({
  flush: jest.fn().mockResolvedValue(undefined),
}));

// Mock Session module
jest.mock("../src/Session", () => ({
  getSessionData: jest.fn(() => ({
    session_id: "mock-session-id",
    distinct_id_snapshot: "test-client-id",
    device_type: "desktop",
    platform: "Unknown",
    browser: "Unknown",
    country: "",
    city: "",
    ip_address: null,
    user_agent: "Unknown",
  })),
}));

// Mock global fetch for sendNormally
global.fetch = jest.fn(() =>
  Promise.resolve({
    ok: true,
    json: () => Promise.resolve({}),
  })
) as jest.Mock;

// Mock navigator object for sendWithBeacon
(global as any).navigator = {
  sendBeacon: jest.fn(() => true),
};

describe("Pusher", () => {
  const createMockEvent = (id: number): Event => ({
    eventName: `event_${id}`,
    eventId: crypto.randomUUID(),
    properties: { id },
    user: `user_${id}`,
    anon_id: crypto.randomUUID(),
    at: Date.now(),
  });

  beforeEach(() => {
    // Reset state before each test
    Configuration.setBatchSize(10);
    Configuration.setHeaders({});
    Configuration.setToken(null);
    jest.clearAllMocks();
    Batcher.reset();
  });

  describe("pushLogs", () => {
    it("should return null when no batches are available", async () => {
      const result = await Pusher.pushLogs();
      expect(result).toBeNull();
    });

    it("should fetch batch from Batcher", async () => {
      // Add some events
      for (let i = 1; i <= 5; i++) {
        Batcher.addToBatch(createMockEvent(i));
      }

      const result = await Pusher.pushLogs();
      expect(result).not.toBeNull();
      expect(result).toHaveLength(5);
    });

    it("should call fetch endpoint with batch data", async () => {
      // Add events to create a batch
      Configuration.setEndpoint("http://localhost:3000/push_batch");
      Configuration.setBatchSize(3);
      for (let i = 1; i <= 3; i++) {
        Batcher.addToBatch(createMockEvent(i));
      }

      await Pusher.pushLogs();

      expect(fetch).toHaveBeenCalledWith(
        "http://localhost:3000/push_batch",
        expect.objectContaining({
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
        })
      );
    });

    it("should handle successful upload", async () => {
      // Add events to create a batch
      Configuration.setBatchSize(3);
      for (let i = 1; i <= 3; i++) {
        Batcher.addToBatch(createMockEvent(i));
      }

      const result = await Pusher.pushLogs();
      expect(result).not.toBeNull();
      expect(result).toHaveLength(3);
    });

    it("should handle failed upload", async () => {
      // Mock fetch failure
      (global.fetch as jest.Mock).mockRejectedValueOnce(new Error("Network error"));

      // Add events to create a batch
      Configuration.setBatchSize(3);
      for (let i = 1; i <= 3; i++) {
        Batcher.addToBatch(createMockEvent(i));
      }

      const result = await Pusher.pushLogs();
      expect(result).toBeNull();
    });

    it("should handle multiple sequential calls", async () => {
      Configuration.setBatchSize(2);

      // Add 4 events (2 batches)
      for (let i = 1; i <= 4; i++) {
        Batcher.addToBatch(createMockEvent(i));
      }

      // First push
      const result1 = await Pusher.pushLogs();
      expect(result1).toHaveLength(2);

      // Mark first batch as uploaded
      Batcher.setMarkLastBatchUploaded();

      // Second push
      const result2 = await Pusher.pushLogs();
      expect(result2).toHaveLength(2);
    });

    it("should handle useBeacon parameter", async () => {
      Configuration.setBatchSize(2);

      for (let i = 1; i <= 2; i++) {
        Batcher.addToBatch(createMockEvent(i));
      }

      const result = await Pusher.pushLogs(true);

      // Beacon doesn't return the batch
      expect(result).toBeNull();
      expect(navigator.sendBeacon).toHaveBeenCalled();
    });

    it("should be async and return Promise", async () => {
      const result = Pusher.pushLogs();

      expect(result).toBeInstanceOf(Promise);
      await result;
    });
  });

  describe("startScheduler", () => {
    it("should start a scheduler with the given interval", () => {
      const { flush } = require("../src/Flush");
      jest.useFakeTimers();

      Pusher.startScheduler(1000);

      // Advance time by 1 second
      jest.advanceTimersByTime(1000);

      expect(flush).toHaveBeenCalled();

      jest.useRealTimers();
    });

    it("should call flush repeatedly at the specified interval", () => {
      const { flush } = require("../src/Flush");
      jest.useFakeTimers();

      Pusher.startScheduler(500);

      // Advance time by 1.5 seconds (3 intervals)
      jest.advanceTimersByTime(1500);

      expect(flush).toHaveBeenCalledTimes(3);

      jest.useRealTimers();
    });
  });

  describe("static behavior", () => {
    it("should not require instantiation", () => {
      jest.useFakeTimers();
      expect(() => {
        Pusher.pushLogs();
        Pusher.startScheduler(1000);
      }).not.toThrow();
      jest.useRealTimers();
    });

    it("should maintain state across calls", async () => {
      Configuration.setBatchSize(2);

      Batcher.addToBatch(createMockEvent(1));
      Batcher.addToBatch(createMockEvent(2));

      const result = await Pusher.pushLogs();

      expect(result).not.toBeNull();
    });
  });

  describe("integration with Batcher", () => {
    it("should work with Batcher to fetch batches", async () => {
      Configuration.setBatchSize(3);

      // Add events
      for (let i = 1; i <= 6; i++) {
        Batcher.addToBatch(createMockEvent(i));
      }

      // First push
      const result1 = await Pusher.pushLogs();
      expect(result1).toHaveLength(3);

      // Mark first batch as uploaded
      Batcher.setMarkLastBatchUploaded();

      // Second push
      const result2 = await Pusher.pushLogs();
      expect(result2).toHaveLength(3);
    });
  });

  describe("setEndpoint", () => {
    it("should allow changing the endpoint", () => {
      const newEndpoint = "https://api.example.com/events";
      Configuration.setEndpoint(newEndpoint);

      // Verify by checking if fetch is called with the new endpoint
      Configuration.setBatchSize(2);
      for (let i = 1; i <= 2; i++) {
        Batcher.addToBatch(createMockEvent(i));
      }

      Pusher.pushLogs();

      expect(fetch).toHaveBeenCalledWith(
        newEndpoint,
        expect.any(Object)
      );
    });
  });

  describe("custom headers", () => {
    it("should include custom headers in fetch request", async () => {
      Configuration.setEndpoint("http://localhost:3000/push_batch");
      Configuration.setBatchSize(2);
      Configuration.setHeaders({
        "X-Api-Key": "test-api-key",
        "X-Request-Id": "12345",
      });

      for (let i = 1; i <= 2; i++) {
        Batcher.addToBatch(createMockEvent(i));
      }

      await Pusher.pushLogs();

      expect(fetch).toHaveBeenCalledWith(
        "http://localhost:3000/push_batch",
        expect.objectContaining({
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "X-Api-Key": "test-api-key",
            "X-Request-Id": "12345",
          },
        })
      );
    });

    it("should include Authorization header when token is set", async () => {
      Configuration.setEndpoint("http://localhost:3000/push_batch");
      Configuration.setBatchSize(2);
      Configuration.setHeaders({
        "X-Custom-Header": "custom-value",
      });
      Configuration.setToken("my-auth-token");

      for (let i = 1; i <= 2; i++) {
        Batcher.addToBatch(createMockEvent(i));
      }

      await Pusher.pushLogs();

      expect(fetch).toHaveBeenCalledWith(
        "http://localhost:3000/push_batch",
        expect.objectContaining({
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "X-Custom-Header": "custom-value",
            "Authorization": "Bearer my-auth-token",
          },
        })
      );
    });
  });

  describe("edge cases", () => {
    it("should handle empty batches", async () => {
      // Empty batches return null from fetchBatchToUpload
      const result = await Pusher.pushLogs();
      expect(result).toBeNull();
    });
  });
});

import { flush } from '../src/Flush';
import { Pusher } from '../src/Pusher';
import { Batcher } from '../src/Batcher';
import { Configuration } from '../src/Configuration';
import type { Event } from '../src/types';

describe('flush', () => {
  beforeEach(() => {
    // Reset state before each test
    Configuration.setBatchSize(10);
    Pusher['_isUploadInProgress'] = false;
    Batcher.reset();
    jest.clearAllMocks();
  });

  const createMockEvent = (id: number): Event => ({
    eventName: `event_${id}`,
    eventId: crypto.randomUUID(),
    properties: { id },
    user: `user_${id}`,
    anon_id: crypto.randomUUID(),
    at: Date.now(),
  });

  describe('basic functionality', () => {
    it('should call Pusher.pushLogs at least once', async () => {
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs').mockResolvedValue(null);

      await flush();

      expect(pushLogsSpy).toHaveBeenCalled();
      pushLogsSpy.mockRestore();
    });

    it('should return when Pusher.pushLogs returns null', async () => {
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs').mockResolvedValue(null);

      await flush();

      expect(pushLogsSpy).toHaveBeenCalledTimes(1);
      pushLogsSpy.mockRestore();
    });

    it('should call Batcher.setMarkLastBatchUploaded when pushLogs returns non-null', async () => {
      const mockBatch: Event[] = [createMockEvent(1)];
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs').mockResolvedValue(mockBatch);
      const markUploadedSpy = jest.spyOn(Batcher, 'setMarkLastBatchUploaded');

      // Mock pushLogs to return null on second call to exit the loop
      pushLogsSpy
        .mockResolvedValueOnce([createMockEvent(1)])
        .mockResolvedValueOnce(null);

      await flush();

      expect(markUploadedSpy).toHaveBeenCalledTimes(1);
      pushLogsSpy.mockRestore();
      markUploadedSpy.mockRestore();
    });

    it('should continue looping until pushLogs returns null', async () => {
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs');
      const markUploadedSpy = jest.spyOn(Batcher, 'setMarkLastBatchUploaded');

      // Simulate 3 batches, then return null
      pushLogsSpy
        .mockResolvedValueOnce([createMockEvent(1)])
        .mockResolvedValueOnce([createMockEvent(2)])
        .mockResolvedValueOnce([createMockEvent(3)])
        .mockResolvedValueOnce(null);

      await flush();

      expect(pushLogsSpy).toHaveBeenCalledTimes(4);
      expect(markUploadedSpy).toHaveBeenCalledTimes(3);
      pushLogsSpy.mockRestore();
      markUploadedSpy.mockRestore();
    });
  });

  describe('integration with Pusher', () => {
    it('should work with Pusher to upload batches', async () => {
      // Add some batches
      Configuration.setBatchSize(2);

      for (let i = 1; i <= 6; i++) {
        Batcher.addToBatch(createMockEvent(i));
      }

      // Mock pushLogs to return batches and then null
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs');
      pushLogsSpy
        .mockResolvedValueOnce([createMockEvent(1), createMockEvent(2)])
        .mockResolvedValueOnce([createMockEvent(3), createMockEvent(4)])
        .mockResolvedValueOnce([createMockEvent(5), createMockEvent(6)])
        .mockResolvedValueOnce(null);

      await flush();

      expect(pushLogsSpy).toHaveBeenCalledTimes(4);
      pushLogsSpy.mockRestore();
    });

    it('should handle Pusher concurrent upload prevention', async () => {
      Pusher['_isUploadInProgress'] = true;

      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs').mockResolvedValue(null);

      await flush();

      expect(pushLogsSpy).toHaveBeenCalled();
      pushLogsSpy.mockRestore();
    });
  });

  describe('integration with Batcher', () => {
    it('should mark batches as uploaded', async () => {
      const markUploadedSpy = jest.spyOn(Batcher, 'setMarkLastBatchUploaded');
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs');

      pushLogsSpy
        .mockResolvedValueOnce([createMockEvent(1)])
        .mockResolvedValueOnce([createMockEvent(2)])
        .mockResolvedValueOnce(null);

      await flush();

      expect(markUploadedSpy).toHaveBeenCalledTimes(2);
      pushLogsSpy.mockRestore();
      markUploadedSpy.mockRestore();
    });

    it('should increment _currentBatchToUpload correctly', async () => {
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs');
      pushLogsSpy
        .mockResolvedValueOnce([createMockEvent(1)])
        .mockResolvedValueOnce([createMockEvent(2)])
        .mockResolvedValueOnce(null);

      await flush();

      expect(Batcher['_currentBatchToUpload']).toBe(2);
      pushLogsSpy.mockRestore();
    });
  });

  describe('edge cases', () => {
    it('should handle empty batches', async () => {
      Batcher.reset();

      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs');
      pushLogsSpy
        .mockResolvedValueOnce([])
        .mockResolvedValueOnce(null);

      await flush();

      expect(pushLogsSpy).toHaveBeenCalledTimes(2);
      pushLogsSpy.mockRestore();
    });

    it('should handle single batch', async () => {
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs');
      pushLogsSpy.mockResolvedValueOnce(null);

      await flush();

      expect(pushLogsSpy).toHaveBeenCalledTimes(1);
      pushLogsSpy.mockRestore();
    });

    it('should handle many batches', async () => {
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs');
      const markUploadedSpy = jest.spyOn(Batcher, 'setMarkLastBatchUploaded');

      // Simulate 10 batches
      pushLogsSpy.mockResolvedValueOnce([createMockEvent(1)])
        .mockResolvedValueOnce([createMockEvent(2)])
        .mockResolvedValueOnce([createMockEvent(3)])
        .mockResolvedValueOnce([createMockEvent(4)])
        .mockResolvedValueOnce([createMockEvent(5)])
        .mockResolvedValueOnce([createMockEvent(6)])
        .mockResolvedValueOnce([createMockEvent(7)])
        .mockResolvedValueOnce([createMockEvent(8)])
        .mockResolvedValueOnce([createMockEvent(9)])
        .mockResolvedValueOnce([createMockEvent(10)])
        .mockResolvedValueOnce(null);

      await flush();

      expect(pushLogsSpy).toHaveBeenCalledTimes(11);
      expect(markUploadedSpy).toHaveBeenCalledTimes(10);
      pushLogsSpy.mockRestore();
      markUploadedSpy.mockRestore();
    });

    it('should be async and return Promise', async () => {
      const result = flush();

      expect(result).toBeInstanceOf(Promise);
      await result;
    });

    it('should handle pushLogs throwing errors', async () => {
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs');
      pushLogsSpy.mockRejectedValue(new Error('Upload failed'));

      await expect(flush()).rejects.toThrow('Upload failed');
      pushLogsSpy.mockRestore();
    });

    it('should handle setMarkLastBatchUploaded throwing errors', async () => {
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs');
      const markUploadedSpy = jest.spyOn(Batcher, 'setMarkLastBatchUploaded');

      pushLogsSpy.mockResolvedValueOnce([createMockEvent(1)]);
      markUploadedSpy.mockImplementation(() => {
        throw new Error('Mark failed');
      });

      await expect(flush()).rejects.toThrow('Mark failed');
      pushLogsSpy.mockRestore();
      markUploadedSpy.mockRestore();
    });
  });

  describe('loop behavior', () => {
    it('should continuously call pushLogs until null is returned', async () => {
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs');
      const markUploadedSpy = jest.spyOn(Batcher, 'setMarkLastBatchUploaded');

      let callCount = 0;
      pushLogsSpy.mockImplementation(() => {
        callCount++;
        if (callCount < 5) {
          return Promise.resolve([createMockEvent(callCount)]);
        }
        return Promise.resolve(null);
      });

      await flush();

      expect(pushLogsSpy).toHaveBeenCalledTimes(5);
      expect(markUploadedSpy).toHaveBeenCalledTimes(4);
      pushLogsSpy.mockRestore();
      markUploadedSpy.mockRestore();
    });

    it('should exit loop immediately when pushLogs returns null on first call', async () => {
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs').mockResolvedValue(null);
      const markUploadedSpy = jest.spyOn(Batcher, 'setMarkLastBatchUploaded');

      await flush();

      expect(pushLogsSpy).toHaveBeenCalledTimes(1);
      expect(markUploadedSpy).not.toHaveBeenCalled();
      pushLogsSpy.mockRestore();
      markUploadedSpy.mockRestore();
    });
  });

  describe('BUG TEST: uses loose equality (==) instead of strict equality (===)', () => {
    it('BUG: line 7 uses == instead of ===', async () => {
      const pushLogsSpy = jest.spyOn(Pusher, 'pushLogs');

      // Test with different falsy values
      pushLogsSpy.mockResolvedValueOnce(null);
      await flush();

      pushLogsSpy.mockResolvedValueOnce(null);
      await flush();

      pushLogsSpy.mockResolvedValueOnce(null);
      await flush();

      pushLogsSpy.mockResolvedValueOnce(null);
      await flush();

      // BUG: The code uses == which means any falsy value will trigger return
      // Should use === to check for null specifically
      expect(pushLogsSpy).toHaveBeenCalled();
      pushLogsSpy.mockRestore();
    });
  });
});

import { Configuration } from '../src/Configuration';

describe('Configuration', () => {
  beforeEach(() => {
    // Reset to default before each test
    Configuration.setBatchSize(10);
    Configuration.setHeaders({});
  });

  describe('batchSize getter', () => {
    it('should return default value of 10', () => {
      expect(Configuration.batchSize).toBe(10);
    });

    it('should return the value that was set', () => {
      Configuration.setBatchSize(20);
      expect(Configuration.batchSize).toBe(20);
    });
  });

  describe('batchSize setter', () => {
    it('should allow setting custom values', () => {
      Configuration.setBatchSize(5);
      expect(Configuration.batchSize).toBe(5);

      Configuration.setBatchSize(100);
      expect(Configuration.batchSize).toBe(100);

      Configuration.setBatchSize(1);
      expect(Configuration.batchSize).toBe(1);
    });

    it('should allow setting to zero', () => {
      Configuration.setBatchSize(0);
      expect(Configuration.batchSize).toBe(0);
    });

    it('should allow setting to negative values', () => {
      Configuration.setBatchSize(-10);
      expect(Configuration.batchSize).toBe(-10);
    });

    it('should allow setting to very large numbers', () => {
      Configuration.setBatchSize(999999);
      expect(Configuration.batchSize).toBe(999999);
    });
  });

